using System.Text.RegularExpressions;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the dependency rule: Domain and Application never reach for technical details.</summary>
public class LayerDependencyTests
{
    private const string Prefix = "PaymentAuthorization.";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions.Http",
        "Microsoft.AspNetCore", "Newtonsoft", "Npgsql", "StackExchange",
    ];

    private static readonly string[] TechnicalTypes =
    [
        "File.", "Directory.", "Path.", "HttpClient", "Process.Start", "Environment.GetEnvironmentVariable",
    ];

    public static TheoryData<string, string[]> Layers => new()
    {
        { "Domain", [] },
        { "Application", ["Domain"] },
    };

    [Theory]
    [MemberData(nameof(Layers))]
    public void Layer_references_only_allowed_layers(string layer, string[] allowed)
    {
        var csproj = Directory.GetFiles(LayerDirectory(layer), "*.csproj").Single();
        var references = Regex.Matches(File.ReadAllText(csproj), "<(?:ProjectReference|PackageReference)\\s+Include=\"([^\"]+)\"")
            .Select(m => Path.GetFileNameWithoutExtension(m.Groups[1].Value.Replace('\\', '/')))
            .ToList();

        var permitted = allowed.Select(a => Prefix + a).ToHashSet();
        Assert.Empty(references.Where(r => !permitted.Contains(r)));
    }

    [Theory]
    [MemberData(nameof(Layers))]
    public void Layer_source_does_not_use_other_layers_or_technical_details(string layer, string[] allowed)
    {
        var forbiddenLayers = new[] { "Domain", "Application", "Infrastructure" }
            .Where(l => l != layer && !allowed.Contains(l))
            .Select(l => Prefix + l);

        var violations = new List<string>();
        foreach (var file in SourceFiles(layer))
        {
            var lines = File.ReadAllLines(file);
            for (var i = 0; i < lines.Length; i++)
            {
                var line = lines[i].Trim();
                if (line.StartsWith("//") || line.StartsWith("///")) continue;

                var isUsing = line.StartsWith("using ") || line.StartsWith("global using ");
                var hit = forbiddenLayers.Any(n => ContainsNamespace(line, n))
                    || TechnicalNamespaces.Any(n => ContainsNamespace(line, n))
                    || (!isUsing && TechnicalTypes.Any(t => Regex.IsMatch(line, @"(?<![\w.])" + Regex.Escape(t))));
                if (hit) violations.Add($"{Path.GetFileName(file)}:{i + 1}: {line}");
            }
        }

        Assert.True(violations.Count == 0, $"{layer} breaks the dependency rule:{Environment.NewLine}{string.Join(Environment.NewLine, violations)}");
    }

    private static bool ContainsNamespace(string line, string ns) => Regex.IsMatch(line, @"(?<![\w.])" + Regex.Escape(ns) + @"(?![\w])");

    private static IEnumerable<string> SourceFiles(string layer) =>
        Directory.EnumerateFiles(LayerDirectory(layer), "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}")
                     && !f.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}"));

    private static string LayerDirectory(string layer)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "PaymentAuthorization.slnx"))) dir = dir.Parent;
        Assert.NotNull(dir);
        return Path.Combine(dir.FullName, "src", Prefix + layer);
    }
}
E
